const rows = $input.all().map((item) => item.json);
const appUrl = 'https://CHANGE-ME.github.io/tenderfit';
const now = new Date();
const parts = new Intl.DateTimeFormat('en', { timeZone: 'Asia/Jerusalem', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(now);
const p = Object.fromEntries(parts.map((part) => [part.type, part.value]));
const today = `${p.year}-${p.month}-${p.day}`;
const sentAt = now.toISOString();
const dayDiff = (date) => Math.round((Date.parse(`${date}T00:00:00.000Z`) - Date.parse(`${today}T00:00:00.000Z`)) / 86400000);
const output = [];
for (const tender of rows) {
  const results = tender.results && typeof tender.results === 'object' ? tender.results : {};
  const responses = results.responses && typeof results.responses === 'object' ? results.responses : {};
  const requirements = new Map((tender.requirements || []).map((item) => [item.requirement_id, item]));
  const dueIds = Object.entries(responses).filter(([, response]) => response?.response_status === 'review' && response.reminder_on && response.reminder_on <= today && !response.reminder_sent_at).map(([id]) => id);
  const deadlineDate = typeof tender.submission_deadline === 'string' ? tender.submission_deadline.slice(0, 10) : null;
  const days = deadlineDate ? dayDiff(deadlineDate) : null;
  const deadlineDue = tender.decision === 'go' && Number.isFinite(days) && days >= 0 && days <= 7;
  if (!deadlineDue && !dueIds.length) continue;
  const lines = [`מכרז: ${tender.title || 'ללא שם'}`];
  if (deadlineDue) lines.push(`מועד ההגשה בעוד ${days} ימים: ${deadlineDate}`);
  if (dueIds.length) {
    lines.push('', 'דרישות שהגיע מועד הבדיקה שלהן:');
    for (const id of dueIds) {
      const response = responses[id];
      lines.push(`• ${requirements.get(id)?.requirement_text || id}`);
      if (response.note) lines.push(`  הערה: ${response.note}`);
    }
  }
  lines.push('', `${appUrl}/tender.html?id=${encodeURIComponent(tender.id)}`);
  const nextResults = structuredClone(results);
  nextResults.responses ||= {};
  for (const id of dueIds) nextResults.responses[id] = { ...nextResults.responses[id], reminder_sent_at: sentAt };
  output.push({ json: { tender_id: tender.id, subject: `TenderFit — תזכורת: ${tender.title || 'מכרז'}`, message: lines.join('\n'), needs_results_update: dueIds.length > 0, results: nextResults, updated_at: sentAt } });
}
return output;
